/* Realmforge V11.13.0 — Canonical Inventory implementation stages.
   Owns the mature Vault/Pack grid-flow and lossless over-encumbrance layers extracted in V11.13. The mixed V8.2 Pack/Bank/Mastery bootstrap remains historical for now because it also owns skilling and combat-feedback code.
   Exact historical stage source is executed at its original chronological boundary. */
(() => {
  'use strict';
  const RF=window.RF;
  const sources={"js/v10_42.js":"window.RF=window.RF||{};\nRF.VERSION='10.42.0';\nRF.BUILD={\n  version:'10.42.0',\n  title:'Vault Grid',\n  built:'16 Sep 2026 • 22:15 BST',\n  buildId:'20260916-2215-bst'\n};\nRF.V1042=RF.V1042||{};\n\n/* Realmforge V10.42 — Vault Grid\n   - Rebuilds Bank into a sleek Pack/Bank tab interface using a 3-column item grid.\n   - Tapping a stack now moves it instantly when only 1 can move, or opens a quantity popup for larger stacks.\n   - Press and hold any bank tile to inspect item details without leaving the Vault.\n   - Aligns the Bank with the newer Skills and navigation-grid design direction.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1042;\nV.HOLD_MS=650;\nV.MOVE_CANCEL_PX=14;\n\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.42.0';\n  s.v1042=s.v1042||{};\n  if(!s.v1042.bankTab)s.v1042.bankTab='pack';\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\nV.escape=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nV.cap=s=>RF.packCapacity?RF.packCapacity(s):(RF.V82?.PACK_CAP||28);\nV.tab=s=>s?.v1042?.bankTab||'pack';\nV.setTab=function(s,tab){\n  s.v1042=s.v1042||{};\n  s.v1042.bankTab=tab==='bank'?'bank':'pack';\n  if(RF.UI.modal?.type==='bank')delete RF.UI.modal.v1042Qty;\n  RF.save?.(s);RF.UI.render(s);\n};\nV.sortedEntries=function(obj){\n  if(RF.V1012?.sortedEntries)return RF.V1012.sortedEntries(obj||{});\n  return Object.entries(obj||{}).sort((a,b)=>{\n    const an=RF.DATA.items?.[a[0]]?.name||a[0],bn=RF.DATA.items?.[b[0]]?.name||b[0];\n    return an.localeCompare(bn);\n  });\n};\nV.packMovable=function(s,id){\n  const held=Math.max(0,Number(s?.inventory?.[id])||0);\n  const protectedQty=RF.isEquipped?.(s,id)?1:0;\n  return Math.max(0,held-protectedQty);\n};\nV.bankMovable=function(s,id){\n  const held=Math.max(0,Number(s?.bank?.[id])||0);\n  if(!held)return 0;\n  if(!(s?.inventory?.[id]>0)&&RF.packUsed(s)>=V.cap(s))return 0;\n  return held;\n};\nV.moveCount=function(s,side,id){return side==='bank'?V.bankMovable(s,id):V.packMovable(s,id)};\nV.bankStacks=s=>Object.values(s?.bank||{}).filter(q=>(+q||0)>0).length;\nV.entries=function(s,side,cat){\n  const source=side==='bank'?(s.bank||{}):(s.inventory||{});\n  return V.sortedEntries(source)\n    .filter(([,q])=>(+q||0)>0)\n    .filter(([id])=>cat==='all'||RF.v92Category(RF.DATA.items[id])===cat)\n    .map(([id,q])=>({id,qty:+q||0,it:RF.DATA.items[id]}))\n    .filter(x=>x.it);\n};\nV.actionWord=side=>side==='bank'?'Withdraw':'Deposit';\nV.sideLabel=side=>side==='bank'?'Bank':'Pack';\nV.stateLine=function(s,side,id,qty){\n  const req=RF.v93Req?.(s,id)||'';\n  const equipped=side==='pack'&&RF.isEquipped?.(s,id);\n  const bits=[`${side==='bank'?'Bank':'Pack'} ×${qty}`];\n  if(equipped)bits.push('Equipped');\n  if(req)bits.push(req);\n  return bits.join(' • ');\n};\nV.tileHtml=function(s,side,row){\n  const {id,qty,it}=row;\n  const movable=V.moveCount(s,side,id);\n  const eq=side==='pack'&&RF.isEquipped?.(s,id);\n  const cls=['v1042BankTile'];\n  if(movable<1)cls.push('disabled');\n  if(eq)cls.push('equipped');\n  return `<button type=\"button\" class=\"${cls.join(' ')}\" data-v1042-bank-tile=\"${V.escape(id)}\" data-v1042-bank-side=\"${side}\" data-v1042-bank-info=\"${V.escape(id)}\" aria-label=\"${V.escape(it.name)}\">\n    <div class=\"v1042TileIcon\">${it.icon||'📦'}</div>\n    <div class=\"v1042TileName\">${V.escape(it.name)}</div>\n    <div class=\"v1042TileMeta\">${side==='bank'?'Bank':'Pack'} ×${qty}</div>\n    <div class=\"v1042TileFoot\">\n      <span class=\"v1042TileQty\">×${qty}</span>\n      ${eq?'<span class=\"v1042TileBadge\">EQ</span>':movable<1?'<span class=\"v1042TileBadge muted\">LOCK</span>':'<span class=\"v1042TileBadge\">MOVE</span>'}\n    </div>\n  </button>`;\n};\nV.itemInfo=function(s,id){\n  const it=RF.DATA.items?.[id];\n  if(!it)return null;\n  const req=RF.itemRequirement?.(it);\n  const rows=[];\n  rows.push(['Type',it.rarity||it.type||'Item']);\n  rows.push(['In Pack',String(Math.max(0,Number(s?.inventory?.[id])||0))]);\n  rows.push(['In Bank',String(Math.max(0,Number(s?.bank?.[id])||0))]);\n  if(it.value!=null)rows.push(['Value',`${it.value}g`]);\n  if(req)rows.push(['Requirement',`${RF.DATA.skills?.[req.skill]?.name||req.skill} Lv ${req.level} • You: ${s?.skills?.[req.skill]?.level||1}`]);\n  if(it.damage)rows.push(['Damage',String(it.damage)]);\n  if(it.armor)rows.push(['Armour',String(it.armor)]);\n  if(it.heal)rows.push(['Healing',`${it.heal} HP`]);\n  if(it.stamina)rows.push(['Stamina',`${it.stamina} STA`]);\n  if(it.slot)rows.push(['Equipment slot',String(it.slot)]);\n  return {icon:it.icon||'📦',name:it.name||id,desc:it.desc||'No description recorded.',rows};\n};\nV.closeInfo=function(){document.querySelector('.v1042BankInfoBack')?.remove()};\nV.showInfo=function(id){\n  const s=RF.state,info=V.itemInfo(s,id); if(!info)return;\n  V.closeInfo();\n  const back=document.createElement('div');\n  back.className='v1042BankInfoBack';\n  back.innerHTML=`<div class=\"v1042BankInfoModal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"${V.escape(info.name)} details\">\n    <div class=\"v1042BankInfoHero\"><div class=\"v1042BankInfoIcon\">${info.icon}</div><div><span class=\"eyebrow\">ITEM DETAILS</span><h2>${V.escape(info.name)}</h2></div></div>\n    <p class=\"v1042BankInfoDesc\">${V.escape(info.desc)}</p>\n    <div class=\"v1042BankInfoRows\">${info.rows.map(([k,v])=>`<div><span>${V.escape(k)}</span><b>${V.escape(v)}</b></div>`).join('')}</div>\n    <button class=\"v1042BankInfoClose\">Close</button>\n  </div>`;\n  document.body.appendChild(back);\n  back.addEventListener('click',e=>{if(e.target===back||e.target.closest('.v1042BankInfoClose'))V.closeInfo()});\n  RF.Platform?.active?.vibrate?.(18);\n};\nV.openQty=function(side,id){\n  if(RF.UI.modal?.type!=='bank')return;\n  RF.UI.modal.v1042Qty={side,id};\n  RF.UI.render(RF.state);\n};\nV.closeQty=function(){\n  if(RF.UI.modal?.type==='bank'&&RF.UI.modal.v1042Qty){delete RF.UI.modal.v1042Qty;RF.UI.render(RF.state)}\n};\nV.transfer=function(side,id,qty){\n  const s=RF.state;if(!s||!RF.isBankTown?.(s))return;\n  qty=Math.max(1,Math.floor(Number(qty)||1));\n  if(side==='pack'){\n    const movable=V.packMovable(s,id),q=Math.min(qty,movable);\n    if(q<1){RF.animateDenied?.(`[data-v1042-bank-tile=\"${id}\"]`);return;}\n    RF.takeItem(s,id,q);\n    s.bank=s.bank||{};\n    s.bank[id]=(s.bank[id]||0)+q;\n    s.stats=s.stats||{};s.stats.bankTransfers=(s.stats.bankTransfers||0)+q;\n    RF.log?.(s,`Deposited ${q} × ${RF.DATA.items?.[id]?.name||id}.`);\n  }else{\n    const movable=V.bankMovable(s,id),q=Math.min(qty,movable);\n    if(q<1){RF.animateDenied?.(`[data-v1042-bank-tile=\"${id}\"]`);return;}\n    s.inventory=s.inventory||{};\n    if(!(s.inventory[id]>0)&&RF.packUsed(s)>=V.cap(s)){RF.animateDenied?.(`[data-v1042-bank-tile=\"${id}\"]`);return;}\n    s.bank[id]-=q;if(s.bank[id]<=0)delete s.bank[id];\n    s.inventory[id]=(s.inventory[id]||0)+q;\n    s.stats=s.stats||{};s.stats.bankTransfers=(s.stats.bankTransfers||0)+q;\n    RF.log?.(s,`Withdrew ${q} × ${RF.DATA.items?.[id]?.name||id}.`);\n  }\n  if(RF.UI.modal?.type==='bank')delete RF.UI.modal.v1042Qty;\n  RF.save?.(s);RF.UI.render(s);\n};\nV.tileTap=function(side,id){\n  const s=RF.state,count=V.moveCount(s,side,id);\n  if(count<1){RF.animateDenied?.(`[data-v1042-bank-tile=\"${id}\"]`);return;}\n  if(count===1)V.transfer(side,id,1);\n  else V.openQty(side,id);\n};\nV.qtyPopup=function(s,m){\n  const qd=m?.v1042Qty;if(!qd)return '';\n  const side=qd.side==='bank'?'bank':'pack',id=qd.id,it=RF.DATA.items?.[id];\n  if(!it)return '';\n  const max=V.moveCount(s,side,id),act=V.actionWord(side);\n  const quick=[1,2,5,10];\n  return `<div class=\"v1042QtyBack\" data-v1042-qty-back>\n    <div class=\"v1042QtyModal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"${V.escape(act)} ${V.escape(it.name)}\">\n      <div class=\"v1042QtyHero\"><div class=\"v1042QtyIcon\">${it.icon||'📦'}</div><div><span class=\"eyebrow\">${V.escape(side==='bank'?'WITHDRAW FROM BANK':'DEPOSIT TO BANK')}</span><h3>${V.escape(it.name)}</h3><div class=\"sub\">Choose how many to ${act.toLowerCase()}.</div></div></div>\n      <div class=\"v1042QtyQuick\">${quick.map(n=>`<button type=\"button\" data-v1042-qty-quick=\"${n}\" ${n>max?'disabled':''}>${n}</button>`).join('')}<button type=\"button\" data-v1042-qty-all ${max<1?'disabled':''}>All</button></div>\n      <label class=\"v1042QtyCustom\">Custom amount<input data-v1042-qty-input type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"${max}\" value=\"${Math.min(max,1)}\"></label>\n      <div class=\"v1042QtyFoot\"><button type=\"button\" class=\"v1042QtyMove\" data-v1042-qty-move ${max<1?'disabled':''}>${V.escape(act)} X</button><button type=\"button\" class=\"v1042QtyCancel\" data-v1042-qty-cancel>Cancel</button></div>\n      <div class=\"tiny center\">Available to move: ${max}</div>\n    </div>\n  </div>`;\n};\nV.bindTile=function(btn){\n  if(!btn||btn.dataset.v1042Bound==='1')return;\n  btn.dataset.v1042Bound='1';\n  let timer=0,startX=0,startY=0,longFired=false,activePointer=null;\n  const cancel=()=>{if(timer){clearTimeout(timer);timer=0}btn.classList.remove('holding');activePointer=null};\n  btn.addEventListener('pointerdown',e=>{\n    if(e.pointerType==='mouse'&&e.button!==0)return;\n    cancel();longFired=false;activePointer=e.pointerId;startX=e.clientX;startY=e.clientY;\n    btn.classList.add('holding');\n    timer=setTimeout(()=>{timer=0;longFired=true;btn.classList.remove('holding');V.showInfo(btn.dataset.v1042BankInfo)},V.HOLD_MS);\n  });\n  btn.addEventListener('pointermove',e=>{if(activePointer!==e.pointerId)return;if(Math.hypot(e.clientX-startX,e.clientY-startY)>V.MOVE_CANCEL_PX)cancel();});\n  btn.addEventListener('pointerup',cancel);btn.addEventListener('pointercancel',cancel);btn.addEventListener('lostpointercapture',cancel);btn.addEventListener('contextmenu',e=>e.preventDefault());\n  btn.addEventListener('click',e=>{\n    if(longFired){longFired=false;e.preventDefault();e.stopImmediatePropagation();return;}\n    e.preventDefault();e.stopImmediatePropagation();\n    V.tileTap(btn.dataset.v1042BankSide,btn.dataset.v1042BankTile);\n  },true);\n};\n\nconst modalBase=RF.UI.modalHtml.bind(RF.UI);\nRF.UI.modalHtml=function(s){\n  const m=this.modal;\n  if(m?.type!=='bank')return modalBase(s);\n  if(!RF.isBankTown(s))return `<div class=\"modalBack\"><div class=\"modal\"><div style=\"font-size:42px\">🏦</div><h2>Bank Unavailable</h2><div class=\"sub\">Your vault can only be accessed from town banks.</div><div class=\"choices\"><button class=\"choice\" data-close-bank><b>Close</b></button></div></div></div>`;\n  const tab=V.tab(s),cat=s.v93?.bankCategory||'all',cap=V.cap(s),used=RF.packUsed(s),bankStacks=V.bankStacks(s),rows=V.entries(s,tab,cat),loc=RF.DATA.locations?.[s.location],label=tab==='bank'?'stored stacks':'slots';\n  const grid=rows.map(r=>V.tileHtml(s,tab,r)).join('');\n  return `<div class=\"modalBack\"><div class=\"modal bankModal v1042VaultModal\">\n    <div class=\"v1042VaultHead\"><div><span class=\"eyebrow\">${V.escape((loc?.name||'Town').toUpperCase())} BANK</span><h2>${loc?.icon||'🏦'} Vault</h2><div class=\"sub\">Tap to move • hold for details</div></div><button class=\"v1042VaultClose\" type=\"button\" data-close-bank aria-label=\"Close Bank\">✕</button></div>\n    <div class=\"v1042VaultTabs\">\n      <button type=\"button\" class=\"v1042VaultTab ${tab==='pack'?'active':''}\" data-v1042-bank-tab=\"pack\"><span>🎒 Pack</span><b>${used}/${cap}</b></button>\n      <button type=\"button\" class=\"v1042VaultTab ${tab==='bank'?'active':''}\" data-v1042-bank-tab=\"bank\"><span>🏦 Bank</span><b>${bankStacks} stacks</b></button>\n    </div>\n    <div class=\"v1042VaultTools\">${RF.v93Select('bank',cat)}<div class=\"v1042VaultCount\">${tab==='pack'?`${used}/${cap}`:`${bankStacks}`} ${label}</div></div>\n    <div class=\"v1042VaultGridWrap\">\n      <div class=\"v1042VaultGrid\">${grid||`<div class=\"v1042VaultEmpty\">Nothing in this category.</div>`}</div>\n    </div>\n    <div class=\"v1042VaultFoot\"><button class=\"quietClose\" data-close-bank>Close Bank</button></div>\n    ${V.qtyPopup(s,m)}\n  </div></div>`;\n};\n\nconst bindBase=RF.UI.bind.bind(RF.UI);\nRF.UI.bind=function(s){\n  bindBase(s);\n  document.querySelectorAll('[data-v1042-bank-tab]').forEach(b=>b.onclick=()=>V.setTab(s,b.dataset.v1042BankTab));\n  document.querySelectorAll('.v1042BankTile[data-v1042-bank-info]').forEach(V.bindTile);\n  document.querySelector('[data-v1042-qty-cancel]')?.addEventListener('click',()=>V.closeQty());\n  document.querySelector('[data-v1042-qty-back]')?.addEventListener('click',e=>{if(e.target===e.currentTarget)V.closeQty()});\n  document.querySelectorAll('[data-v1042-qty-quick]').forEach(b=>b.onclick=()=>{const q=+b.dataset.v1042QtyQuick||1,m=RF.UI.modal?.v1042Qty;if(m)V.transfer(m.side,m.id,q)});\n  document.querySelector('[data-v1042-qty-all]')?.addEventListener('click',()=>{const m=RF.UI.modal?.v1042Qty;if(m)V.transfer(m.side,m.id,V.moveCount(RF.state,m.side,m.id))});\n  document.querySelector('[data-v1042-qty-move]')?.addEventListener('click',()=>{\n    const m=RF.UI.modal?.v1042Qty;if(!m)return;\n    const input=document.querySelector('[data-v1042-qty-input]');\n    const max=V.moveCount(RF.state,m.side,m.id),q=Math.max(1,Math.min(max,Math.floor(+input?.value||1)));\n    V.transfer(m.side,m.id,q);\n  });\n};\n\nconst renderBase=RF.UI.render.bind(RF.UI);\nRF.UI.render=function(s){\n  if(this.modal?.type!=='bank')V.closeInfo();\n  return renderBase(s);\n};\n\nconst st=document.createElement('style');st.id='v1042-vault-grid-style';st.textContent=`\n.v1042VaultModal{width:min(740px,100%);height:min(89dvh,860px);max-height:89dvh;display:grid;grid-template-rows:auto auto auto minmax(0,1fr) auto;gap:12px;overflow:hidden;padding:18px 14px 14px}\n.v1042VaultHead{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.v1042VaultHead h2{margin:2px 0 0;color:#f1d496;font-size:25px}.v1042VaultHead .sub{margin-top:4px;color:#b7a78a}\n.v1042VaultClose{width:42px;height:42px;border-radius:13px;border:1px solid rgba(214,173,96,.28);background:linear-gradient(180deg,rgba(52,38,22,.85),rgba(25,19,13,.95));color:#edd6a0;font-size:20px;display:grid;place-items:center;flex:0 0 auto}\n.v1042VaultTabs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.v1042VaultTab{appearance:none;border:1px solid rgba(201,159,84,.24);border-radius:16px;background:linear-gradient(180deg,rgba(46,34,21,.76),rgba(20,15,10,.95));padding:12px 14px;display:flex;align-items:center;justify-content:space-between;gap:10px;color:#e5d1a3;text-align:left;box-shadow:inset 0 1px rgba(255,255,255,.05)}.v1042VaultTab span{font-weight:800}.v1042VaultTab b{font-size:12px;color:#b8a991;font-weight:700}.v1042VaultTab.active{border-color:#c69d59;background:linear-gradient(180deg,rgba(96,67,29,.95),rgba(40,28,17,.98));box-shadow:0 0 0 1px rgba(198,157,89,.16) inset,0 10px 26px #0003}\n.v1042VaultTools{display:flex;align-items:end;justify-content:space-between;gap:10px}.v1042VaultTools .filterSelect{flex:1 1 auto;margin:0}.v1042VaultTools .filterSelect span{text-transform:uppercase;letter-spacing:.14em}.v1042VaultCount{flex:0 0 auto;font-size:11px;color:#b4a489;padding-bottom:3px}\n.v1042VaultGridWrap{min-height:0;overflow:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;border:1px solid rgba(198,158,83,.18);border-radius:18px;background:linear-gradient(180deg,rgba(13,10,8,.28),rgba(9,7,6,.42));padding:10px}\n.v1042VaultGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;align-content:start}\n.v1042BankTile{appearance:none;position:relative;min-height:132px;border-radius:18px;border:1px solid rgba(201,159,84,.18);background:linear-gradient(180deg,rgba(43,32,21,.92),rgba(18,13,10,.98));padding:12px 10px 10px;color:#f3e1bb;text-align:left;display:flex;flex-direction:column;align-items:flex-start;gap:7px;box-shadow:inset 0 1px rgba(255,255,255,.035);-webkit-touch-callout:none;user-select:none;touch-action:manipulation}\n.v1042BankTile.holding{outline:1px solid #bc8b45;box-shadow:0 0 0 1px #bc8b4528 inset}.v1042BankTile.holding:after{content:'';position:absolute;left:0;bottom:0;height:3px;background:#d8ae63;animation:v1042HoldFill .65s linear forwards;width:0}.v1042BankTile.disabled{opacity:.52;filter:saturate(.65)}.v1042BankTile.equipped{border-color:rgba(106,151,110,.34)}\n@keyframes v1042HoldFill{from{width:0}to{width:100%}}\n.v1042TileIcon{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;font-size:30px;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.01));border:1px solid rgba(223,183,104,.14)}\n.v1042TileName{font-weight:800;line-height:1.12;font-size:14px;min-height:31px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.v1042TileMeta{font-size:10px;line-height:1.25;color:#ad9c80;min-height:24px}.v1042TileFoot{margin-top:auto;width:100%;display:flex;align-items:center;justify-content:space-between;gap:8px}.v1042TileQty{font-weight:800;font-size:14px;color:#f2d89b}.v1042TileBadge{font-size:9px;font-weight:800;letter-spacing:.08em;border:1px solid rgba(208,167,87,.28);padding:4px 6px;border-radius:999px;background:rgba(208,167,87,.08);color:#d9c18f}.v1042TileBadge.muted{background:rgba(255,255,255,.04);color:#b5a58b;border-color:rgba(255,255,255,.08)}\n.v1042VaultEmpty{grid-column:1/-1;padding:30px 14px;text-align:center;color:#b9ab94;font-size:13px}\n.v1042VaultFoot{display:flex}.v1042VaultFoot .quietClose{width:100%;margin:0}\n.v1042QtyBack{position:absolute;inset:0;z-index:30;background:#080604cc;backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:14px}.v1042QtyModal{width:min(430px,100%);border:1px solid #775c38;border-radius:18px;background:linear-gradient(180deg,#21190f,#15110d);box-shadow:0 22px 60px #000b;padding:16px}.v1042QtyHero{display:flex;gap:12px;align-items:center}.v1042QtyIcon{width:54px;height:54px;border-radius:15px;display:grid;place-items:center;font-size:30px;background:#2a2117;border:1px solid #6b5438}.v1042QtyHero h3{margin:2px 0 0;color:#f0d99f;font-size:22px}.v1042QtyQuick{margin-top:13px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.v1042QtyQuick button,.v1042QtyMove,.v1042QtyCancel{min-height:44px;border-radius:12px;border:1px solid rgba(216,173,87,.42);background:linear-gradient(180deg,rgba(100,71,31,.92),rgba(61,42,21,.95));color:#f6e7c1;font:inherit;font-weight:750}.v1042QtyQuick button:disabled,.v1042QtyMove:disabled{opacity:.38}.v1042QtyCustom{display:grid;gap:6px;margin-top:12px;color:#c2b59d;font-size:12px}.v1042QtyCustom input{height:44px;border-radius:12px;border:1px solid #59442b;background:#0e0b09;color:#f1dfb7;padding:0 12px;font:inherit}.v1042QtyFoot{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.v1042QtyCancel{background:linear-gradient(180deg,rgba(77,62,39,.96),rgba(48,39,27,.96))}\n.v1042BankInfoBack{position:fixed;inset:0;z-index:141;background:#080604c9;backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:18px 14px calc(18px + env(safe-area-inset-bottom))}.v1042BankInfoModal{width:min(430px,100%);max-height:88vh;overflow:auto;border:1px solid #775c38;border-radius:18px;background:linear-gradient(180deg,#21190f,#15110d);box-shadow:0 22px 60px #000b;padding:17px}.v1042BankInfoHero{display:flex;align-items:center;gap:12px;margin-bottom:10px}.v1042BankInfoIcon{width:58px;height:58px;display:grid;place-items:center;border-radius:16px;font-size:34px;background:#2a2117;border:1px solid #6b5438}.v1042BankInfoHero h2{margin:2px 0 0;color:#f0d99f;font-size:25px}.v1042BankInfoDesc{margin:7px 0 13px;color:#c4b79f;line-height:1.45;font-size:13px}.v1042BankInfoRows{border:1px solid #463729;border-radius:13px;overflow:hidden}.v1042BankInfoRows>div{display:grid;grid-template-columns:minmax(95px,.8fr) minmax(0,1.4fr);gap:10px;padding:9px 10px;border-bottom:1px solid #392d23}.v1042BankInfoRows>div:last-child{border-bottom:0}.v1042BankInfoRows span{font-size:10px;color:#958976}.v1042BankInfoRows b{font-size:10px;color:#e5d5b5;text-align:right;line-height:1.3}.v1042BankInfoClose{width:100%;margin-top:13px;min-height:46px;border-radius:12px;border:1px solid #745630;background:#302215;color:#f2dfb7;font-weight:700}\n@media(max-width:430px){.v1042VaultModal{height:91dvh;max-height:91dvh;padding:14px 10px 10px;gap:10px}.v1042VaultHead h2{font-size:23px}.v1042VaultGrid{gap:8px}.v1042BankTile{min-height:122px;padding:10px 8px 8px;border-radius:16px}.v1042TileIcon{width:42px;height:42px;font-size:27px}.v1042TileName{font-size:13px;min-height:28px}.v1042TileMeta{font-size:9.5px}.v1042TileQty{font-size:13px}.v1042TileBadge{font-size:8px;padding:3px 5px}.v1042QtyModal,.v1042BankInfoModal{padding:14px}}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n","js/v10_43.js":"window.RF=window.RF||{};\nRF.VERSION='10.43.0';\nRF.BUILD={\n  version:'10.43.0',\n  title:'Vault Compact',\n  built:'16 Sep 2026 • 22:22 BST',\n  buildId:'20260916-2222-bst'\n};\nRF.V1043=RF.V1043||{};\n\n/* Realmforge V10.43 — Vault Compact\n   - Tightens the V10.42 vault layout into a denser 4-column grid.\n   - Shortens item tiles and removes the redundant Pack/Bank quantity subline.\n   - Reduces item-name sizing so compact tiles still fit neatly on mobile.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1043;\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.43.0';\n  s.v1043=s.v1043||{};\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\nconst oldStyle=document.getElementById('v1043-vault-compact-style');\nif(oldStyle)oldStyle.remove();\nconst st=document.createElement('style');\nst.id='v1043-vault-compact-style';\nst.textContent=`\n.v1042VaultModal{width:min(760px,100%);padding:16px 12px 12px;gap:10px}\n.v1042VaultGridWrap{padding:8px}\n.v1042VaultGrid{grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}\n.v1042BankTile{min-height:104px;padding:9px 7px 8px;border-radius:15px;gap:5px}\n.v1042TileIcon{width:36px;height:36px;border-radius:12px;font-size:24px}\n.v1042TileName{font-size:11px;line-height:1.12;min-height:24px}\n.v1042TileMeta{display:none!important}\n.v1042TileFoot{gap:6px}\n.v1042TileQty{font-size:11px;line-height:1}\n.v1042TileBadge{font-size:8px;padding:3px 5px}\n.v1042VaultHead h2{font-size:24px}\n.v1042VaultHead .sub{font-size:11px}\n.v1042VaultTab{padding:11px 12px;border-radius:15px}\n.v1042VaultTools{gap:8px;align-items:center}\n.v1042VaultCount{font-size:10px;padding-bottom:0}\n@media(max-width:430px){\n  .v1042VaultModal{height:91dvh;max-height:91dvh;padding:12px 8px 10px;gap:9px}\n  .v1042VaultGridWrap{padding:7px}\n  .v1042VaultGrid{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}\n  .v1042BankTile{min-height:98px;padding:8px 6px 7px;border-radius:14px}\n  .v1042TileIcon{width:34px;height:34px;font-size:22px}\n  .v1042TileName{font-size:10.5px;min-height:22px}\n  .v1042TileQty{font-size:10.5px}\n  .v1042TileBadge{font-size:7.5px;padding:3px 4px}\n}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n","js/v10_44.js":"window.RF=window.RF||{};\nRF.VERSION='10.44.0';\nRF.BUILD={\n  version:'10.44.0',\n  title:'Vault Flow',\n  built:'16 Sep 2026 • 22:33 BST',\n  buildId:'20260916-2233-bst'\n};\nRF.V1044=RF.V1044||{};\n\n/* Realmforge V10.44 — Vault Flow\n   - Improves the V10.42/10.43 quantity popup workflow.\n   - Shows the remaining movable amount beside the item name.\n   - Quick quantity buttons no longer close the popup after each transfer, enabling repeated taps.\n   - Adds an in-grid reddish close button and removes the redundant footer availability line.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1044;\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.44.0';\n  s.v1044=s.v1044||{};\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\nconst B=RF.V1042;\nif(B){\n  B.qtyPopup=function(s,m){\n    const qd=m?.v1042Qty;if(!qd)return '';\n    const side=qd.side==='bank'?'bank':'pack',id=qd.id,it=RF.DATA.items?.[id];\n    if(!it)return '';\n    const max=B.moveCount(s,side,id),act=B.actionWord(side);\n    const quick=[1,2,5];\n    return `<div class=\"v1042QtyBack\" data-v1042-qty-back>\n      <div class=\"v1042QtyModal v1044QtyModal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"${B.escape(act)} ${B.escape(it.name)}\">\n        <div class=\"v1042QtyHero\"><div class=\"v1042QtyIcon\">${it.icon||'📦'}</div><div><span class=\"eyebrow\">${B.escape(side==='bank'?'WITHDRAW FROM BANK':'DEPOSIT TO BANK')}</span><h3>${B.escape(it.name)} <span class=\"v1044QtyCount\">×${max}</span></h3><div class=\"sub\">Choose how many to ${act.toLowerCase()}.</div></div></div>\n        <div class=\"v1042QtyQuick v1044QtyQuick\">${quick.map(n=>`<button type=\"button\" data-v1042-qty-quick=\"${n}\" ${n>max?'disabled':''}>${n}</button>`).join('')}<button type=\"button\" data-v1042-qty-quick=\"10\" ${10>max?'disabled':''}>10</button><button type=\"button\" data-v1042-qty-all ${max<1?'disabled':''}>All</button><button type=\"button\" class=\"v1044QtyCloseBtn\" data-v1042-qty-cancel>Close</button></div>\n        <label class=\"v1042QtyCustom\">Custom amount<input data-v1042-qty-input type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"${max}\" value=\"${Math.min(max,1)}\"></label>\n        <div class=\"v1042QtyFoot v1044QtyFoot\"><button type=\"button\" class=\"v1042QtyMove\" data-v1042-qty-move ${max<1?'disabled':''}>${B.escape(act)} X</button></div>\n      </div>\n    </div>`;\n  };\n\n  B.transfer=function(side,id,qty){\n    const s=RF.state;if(!s||!RF.isBankTown?.(s))return;\n    qty=Math.max(1,Math.floor(Number(qty)||1));\n    const keepOpen=RF.UI.modal?.type==='bank' && !!RF.UI.modal?.v1042Qty && RF.UI.modal.v1042Qty.id===id && RF.UI.modal.v1042Qty.side===side;\n    if(side==='pack'){\n      const movable=B.packMovable(s,id),q=Math.min(qty,movable);\n      if(q<1){RF.animateDenied?.(`[data-v1042-bank-tile=\"${id}\"]`);return;}\n      RF.takeItem(s,id,q);\n      s.bank=s.bank||{};\n      s.bank[id]=(s.bank[id]||0)+q;\n      s.stats=s.stats||{};s.stats.bankTransfers=(s.stats.bankTransfers||0)+q;\n      RF.log?.(s,`Deposited ${q} × ${RF.DATA.items?.[id]?.name||id}.`);\n    }else{\n      const movable=B.bankMovable(s,id),q=Math.min(qty,movable);\n      if(q<1){RF.animateDenied?.(`[data-v1042-bank-tile=\"${id}\"]`);return;}\n      s.inventory=s.inventory||{};\n      if(!(s.inventory[id]>0)&&RF.packUsed(s)>=B.cap(s)){RF.animateDenied?.(`[data-v1042-bank-tile=\"${id}\"]`);return;}\n      s.bank[id]-=q;if(s.bank[id]<=0)delete s.bank[id];\n      s.inventory[id]=(s.inventory[id]||0)+q;\n      s.stats=s.stats||{};s.stats.bankTransfers=(s.stats.bankTransfers||0)+q;\n      RF.log?.(s,`Withdrew ${q} × ${RF.DATA.items?.[id]?.name||id}.`);\n    }\n    if(RF.UI.modal?.type==='bank'){\n      const remaining=B.moveCount(s,side,id);\n      if(keepOpen && remaining>0)RF.UI.modal.v1042Qty={side,id};\n      else delete RF.UI.modal.v1042Qty;\n    }\n    RF.save?.(s);RF.UI.render(s);\n  };\n}\n\nconst oldStyle=document.getElementById('v1044-vault-flow-style');\nif(oldStyle)oldStyle.remove();\nconst st=document.createElement('style');\nst.id='v1044-vault-flow-style';\nst.textContent=`\n.v1044QtyModal .v1042QtyHero h3{display:flex;align-items:baseline;gap:7px;flex-wrap:wrap}\n.v1044QtyCount{font-size:18px;color:#d8c08b;font-weight:800}\n.v1044QtyQuick{grid-template-columns:repeat(3,minmax(0,1fr))!important}\n.v1044QtyCloseBtn{background:linear-gradient(180deg,rgba(118,43,43,.96),rgba(76,24,24,.98))!important;border-color:rgba(210,102,102,.42)!important;color:#f5dddd!important}\n.v1044QtyFoot{grid-template-columns:1fr!important}\n.v1044QtyFoot .v1042QtyMove{width:100%}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n","js/v10_45.js":"window.RF=window.RF||{};\nRF.VERSION='10.45.0';\nRF.BUILD={\n  version:'10.45.0',\n  title:'Pack Grid',\n  built:'16 Sep 2026 • 22:52 BST',\n  buildId:'20260916-2252-bst'\n};\nRF.V1045=RF.V1045||{};\n\n/* Realmforge V10.45 — Pack Grid\n   - Rebuilds the main Pack tab into the same compact 4-column grid direction as the Vault.\n   - Replaces inventory category dropdowns with a single-row tab strip.\n   - Applies the new category tabs across inventory-facing interfaces such as Pack and Bank.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1045;\nV.CATS=[\n  ['all','All'],\n  ['weapons','Weapons'],\n  ['armour','Armour'],\n  ['consumables','Food'],\n  ['materials','Mats'],\n  ['tools','Tools'],\n  ['treasure','Treasure'],\n  ['other','Other']\n];\n\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.45.0';\n  s.v1045=s.v1045||{};\n  s.v93=s.v93||{};\n  if(!s.v93.inventoryCategory)s.v93.inventoryCategory='all';\n  if(!s.v93.bankCategory)s.v93.bankCategory='all';\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\nV.escape=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nV.cap=s=>RF.packCapacity?RF.packCapacity(s):(RF.V82?.PACK_CAP||28);\nV.categoryTabs=function(kind,active){\n  return `<div class=\"v1045CatScroller\" role=\"tablist\" aria-label=\"${V.escape(kind)} categories\">${V.CATS.map(([id,label])=>`<button type=\"button\" class=\"v1045CatTab ${active===id?'active':''}\" data-v1045-cat-kind=\"${kind}\" data-v1045-cat=\"${id}\">${V.escape(label)}</button>`).join('')}</div>`;\n};\nRF.v93Select=function(kind,active){return V.categoryTabs(kind,active)};\n\nV.packTile=function(s,id,qty){\n  const it=RF.DATA.items?.[id]; if(!it)return '';\n  const equipped=RF.isEquipped?.(s,id);\n  const can=RF.canEquipItem?.(s,id);\n  const badge=equipped?'<span class=\"v1042TileBadge\">EQ</span>':(it.slot&&!can?'<span class=\"v1042TileBadge muted\">LOCK</span>':'');\n  return `<button type=\"button\" class=\"v1042BankTile v1045PackTile ${equipped?'equipped':''}\" data-item-detail=\"${V.escape(id)}\" aria-label=\"${V.escape(it.name)}\">\n    <div class=\"v1042TileIcon\">${it.icon||'📦'}</div>\n    <div class=\"v1042TileName\">${V.escape(it.name)}</div>\n    <div class=\"v1042TileFoot\"><span class=\"v1042TileQty\">×${qty}</span>${badge}</div>\n  </button>`;\n};\n\nRF.UI.inventory=function(s){\n  const used=RF.packUsed(s),cap=V.cap(s),pct=Math.min(100,used/cap*100),cat=s.v93?.inventoryCategory||'all';\n  const entries=(RF.V1012?.sortedEntries?RF.V1012.sortedEntries(s.inventory):Object.entries(s.inventory||{}))\n    .filter(([,q])=>(+q||0)>0)\n    .filter(([id])=>cat==='all'||RF.v92Category(RF.DATA.items[id])===cat);\n  const tiles=entries.map(([id,q])=>V.packTile(s,id,+q||0)).join('');\n  return `<section class=\"card v1045PackCard\"><div class=\"questTitle\"><h2>Pack</h2><span class=\"packCount ${used>=cap?'full':''}\">${used}/${cap} slots</span></div><div class=\"packBar\"><div style=\"width:${pct}%\"></div></div>${V.categoryTabs('inventory',cat)}${RF.isBankTown(s)?`<button class=\"action bankOpen v1045BankOpen\" data-open-bank><b>🏦 Open Bank</b><small>Deposit or withdraw stored items</small></button>`:'<div class=\"tiny bankHint\">🏦 Bank access: Greenvale, Ironridge and Reedmere.</div>'}<div class=\"v1045PackGridWrap\"><div class=\"v1042VaultGrid v1045PackGrid\">${tiles||'<div class=\"v1042VaultEmpty\">Nothing in this category.</div>'}</div></div></section>`;\n};\n\nconst bindBase=RF.UI.bind.bind(RF.UI);\nRF.UI.bind=function(s){\n  bindBase(s);\n  document.querySelectorAll('[data-v1045-cat-kind]').forEach(b=>b.onclick=()=>{\n    const kind=b.dataset.v1045CatKind,cat=b.dataset.v1045Cat;\n    s.v93=s.v93||{};\n    s.v93[`${kind}Category`]=cat;\n    RF.save?.(s);\n    RF.UI.render(s);\n  });\n};\n\nconst oldStyle=document.getElementById('v1045-pack-grid-style');\nif(oldStyle)oldStyle.remove();\nconst st=document.createElement('style');\nst.id='v1045-pack-grid-style';\nst.textContent=`\n.v1045CatScroller{display:flex;flex-wrap:nowrap;gap:7px;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;scrollbar-width:none;padding:2px 1px 1px}.v1045CatScroller::-webkit-scrollbar{display:none}\n.v1045CatTab{flex:0 0 auto;min-height:34px;padding:0 12px;border-radius:999px;border:1px solid rgba(200,159,84,.22);background:linear-gradient(180deg,rgba(36,27,19,.82),rgba(18,13,10,.94));color:#d7c39a;font-size:11px;font-weight:800;letter-spacing:.02em;white-space:nowrap;box-shadow:inset 0 1px rgba(255,255,255,.04)}\n.v1045CatTab.active{border-color:#c69d59;background:linear-gradient(180deg,rgba(109,76,33,.98),rgba(65,45,22,.98));color:#f5e5bf}\n.v1045PackCard{display:grid;gap:12px}.v1045BankOpen{margin-top:2px}.v1045PackGridWrap{border:1px solid rgba(198,158,83,.16);border-radius:18px;background:linear-gradient(180deg,rgba(13,10,8,.18),rgba(9,7,6,.32));padding:8px;min-height:0}.v1045PackGrid{grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;align-content:start}\n.v1045PackTile{min-height:98px;padding:8px 6px 7px;border-radius:14px}.v1045PackTile .v1042TileIcon{width:34px;height:34px;font-size:22px}.v1045PackTile .v1042TileName{font-size:10.5px;min-height:22px}.v1045PackTile .v1042TileFoot{margin-top:auto}.v1045PackTile .v1042TileQty{font-size:10.5px}.v1045PackTile .v1042TileBadge{font-size:7.5px;padding:3px 4px}\n.v1042VaultTools .v1045CatScroller{flex:1 1 auto}\n@media(min-width:700px){.v1045PackTile{min-height:104px;padding:9px 7px 8px}.v1045PackTile .v1042TileIcon{width:36px;height:36px;font-size:24px}.v1045PackTile .v1042TileName{font-size:11px;min-height:24px}.v1045PackTile .v1042TileQty{font-size:11px}.v1045PackTile .v1042TileBadge{font-size:8px;padding:3px 5px}}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n","js/v10_46.js":"window.RF=window.RF||{};\nRF.VERSION='10.46.0';\nRF.BUILD={\n  version:'10.46.0',\n  title:'Category Grid',\n  built:'16 Sep 2026 • 23:02 BST',\n  buildId:'20260916-2302-bst'\n};\nRF.V1046=RF.V1046||{};\n\n/* Realmforge V10.46 — Category Grid\n   - Reworks the V10.45 category tabs into a tidy 2-row, 4-column layout.\n   - Keeps the new category-tab system while preventing horizontal stretch in Pack and Vault.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1046;\nV.CATS=[\n  ['all','All'],['weapons','Weapons'],['armour','Armour'],['consumables','Food'],\n  ['materials','Mats'],['tools','Tools'],['treasure','Treasure'],['other','Other']\n];\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.46.0';\n  s.v1046=s.v1046||{};\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\nV.escape=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nV.cap=s=>RF.packCapacity?RF.packCapacity(s):(RF.V82?.PACK_CAP||28);\nV.categoryTabs=function(kind,active){\n  return `<div class=\"v1046CatGrid\" role=\"tablist\" aria-label=\"${V.escape(kind)} categories\">${V.CATS.map(([id,label])=>`<button type=\"button\" class=\"v1046CatTab ${active===id?'active':''}\" data-v1045-cat-kind=\"${kind}\" data-v1045-cat=\"${id}\">${V.escape(label)}</button>`).join('')}</div>`;\n};\nRF.v93Select=function(kind,active){return V.categoryTabs(kind,active)};\n\n// Rebuild Pack so it uses the new compact 2x4 category layout too.\nRF.UI.inventory=function(s){\n  const used=RF.packUsed(s),cap=V.cap(s),pct=Math.min(100,used/cap*100),cat=s.v93?.inventoryCategory||'all';\n  const sorted=(RF.V1012?.sortedEntries?RF.V1012.sortedEntries(s.inventory):Object.entries(s.inventory||{}));\n  const entries=sorted.filter(([,q])=>(+q||0)>0).filter(([id])=>cat==='all'||RF.v92Category(RF.DATA.items[id])===cat);\n  const tiles=entries.map(([id,q])=>{\n    const it=RF.DATA.items?.[id]; if(!it)return '';\n    const equipped=RF.isEquipped?.(s,id);\n    const can=RF.canEquipItem?.(s,id);\n    const badge=equipped?'<span class=\"v1042TileBadge\">EQ</span>':(it.slot&&!can?'<span class=\"v1042TileBadge muted\">LOCK</span>':'');\n    return `<button type=\"button\" class=\"v1042BankTile v1045PackTile ${equipped?'equipped':''}\" data-item-detail=\"${V.escape(id)}\" aria-label=\"${V.escape(it.name)}\"><div class=\"v1042TileIcon\">${it.icon||'📦'}</div><div class=\"v1042TileName\">${V.escape(it.name)}</div><div class=\"v1042TileFoot\"><span class=\"v1042TileQty\">×${q}</span>${badge}</div></button>`;\n  }).join('');\n  return `<section class=\"card v1045PackCard\"><div class=\"questTitle\"><h2>Pack</h2><span class=\"packCount ${used>=cap?'full':''}\">${used}/${cap} slots</span></div><div class=\"packBar\"><div style=\"width:${pct}%\"></div></div>${V.categoryTabs('inventory',cat)}${RF.isBankTown(s)?`<button class=\"action bankOpen v1045BankOpen\" data-open-bank><b>🏦 Open Bank</b><small>Deposit or withdraw stored items</small></button>`:'<div class=\"tiny bankHint\">🏦 Bank access: Greenvale, Ironridge and Reedmere.</div>'}<div class=\"v1045PackGridWrap\"><div class=\"v1042VaultGrid v1045PackGrid\">${tiles||'<div class=\"v1042VaultEmpty\">Nothing in this category.</div>'}</div></div></section>`;\n};\n\nconst oldStyle=document.getElementById('v1046-category-grid-style');\nif(oldStyle)oldStyle.remove();\nconst st=document.createElement('style');\nst.id='v1046-category-grid-style';\nst.textContent=`\n.v1046CatGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:stretch}\n.v1046CatTab{min-height:36px;padding:0 6px;border-radius:14px;border:1px solid rgba(200,159,84,.22);background:linear-gradient(180deg,rgba(36,27,19,.82),rgba(18,13,10,.94));color:#d7c39a;font-size:10px;font-weight:800;letter-spacing:.01em;line-height:1.05;white-space:normal;text-align:center;box-shadow:inset 0 1px rgba(255,255,255,.04)}\n.v1046CatTab.active{border-color:#c69d59;background:linear-gradient(180deg,rgba(109,76,33,.98),rgba(65,45,22,.98));color:#f5e5bf}\n.v1042VaultTools .v1046CatGrid{flex:1 1 auto;width:100%}\n.v1042VaultTools{display:grid!important;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:10px}\n.v1042VaultCount{padding-top:5px}\n@media(max-width:430px){\n  .v1046CatGrid{gap:6px}\n  .v1046CatTab{min-height:34px;font-size:9.5px;padding:0 4px;border-radius:13px}\n  .v1042VaultTools{gap:8px}\n}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n","js/v10_47.js":"window.RF=window.RF||{};\nRF.VERSION='10.47.0';\nRF.BUILD={\n  version:'10.47.0',\n  title:'Three Vaults',\n  built:'16 Sep 2026 • 23:12 BST',\n  buildId:'20260916-2312-bst'\n};\nRF.V1047=RF.V1047||{};\n\n/* Realmforge V10.47 — Three Vaults\n   - Removes the redundant bottom Close Bank control from the modern Vault modal.\n   - Restores banking as a regional-town service in Greenvale, Ironridge and Reedmere.\n   - Adds the same dedicated World > Bank section used in Greenvale to Ironridge and Reedmere.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1047;\nV.BANKS=RF.Config.clone(\"services.banks\");\n\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.47.0';\n  s.v1047=s.v1047||{};\n  // Mark these locations as banking settlements for systems that inspect location data directly.\n  ['greenvale','ironridge','reedmere'].forEach(id=>{if(RF.DATA?.locations?.[id])RF.DATA.locations[id].bank=true});\n  return s;\n};\n\n// Restore the original regional-bank geography that V10.10 temporarily narrowed to Greenvale.\nRF.isBankTown=s=>!!s&&!!V.BANKS[s.location];\n['greenvale','ironridge','reedmere'].forEach(id=>{if(RF.DATA?.locations?.[id])RF.DATA.locations[id].bank=true});\n\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\n// Normalize World banking into the same dedicated card at all three banking settlements.\nconst worldBase=RF.UI.world.bind(RF.UI);\nRF.UI.world=function(s){\n  let html=worldBase(s);\n  const bank=V.BANKS[s?.location];\n  if(!bank)return html;\n\n  // Remove any earlier bank button/card so this patch owns one consistent regional-bank section.\n  html=html.replace(/<button class=\"action bankOpen[^>]*data-open-bank[^>]*>[\\s\\S]*?<\\/button>/g,'');\n  html=html.replace(/<section class=\"card v1014BankSection\">[\\s\\S]*?<\\/section>/g,'');\n\n  const disabled=(s.activity||s.combat)?'disabled':'';\n  const section=`<section class=\"card v1014BankSection v1047BankSection\"><h3>Bank</h3><button class=\"action bankOpen v1014BankButton v1047BankButton\" data-open-bank ${disabled}><span class=\"emoji\">${bank.icon}</span><b>${bank.name}</b><small>Deposit or withdraw stored items</small></button></section>`;\n  const travel='<section class=\"card\"><h3>Travel</h3>';\n  if(html.includes(travel))html=html.replace(travel,section+travel);\n  else html+=section;\n  return html;\n};\n\n// Modern Vault already has the top-right X. Remove only its redundant bottom close row.\nconst modalBase=RF.UI.modalHtml.bind(RF.UI);\nRF.UI.modalHtml=function(s){\n  let h=modalBase(s);\n  if(this.modal?.type==='bank'){\n    h=h.replace(/<div class=\"v1042VaultFoot\">[\\s\\S]*?<\\/div>/g,'');\n  }\n  return h;\n};\n\n// V10.10's older bank binder hard-coded Greenvale. Reassert the current geography last.\nconst bindBase=RF.UI.bind.bind(RF.UI);\nRF.UI.bind=function(s){\n  bindBase(s);\n  document.querySelectorAll('[data-open-bank]').forEach(b=>{\n    b.onclick=()=>{\n      if(!RF.isBankTown(RF.state))return;\n      RF.openBank();\n    };\n  });\n};\n\nconst oldStyle=document.getElementById('v1047-three-vaults-style');\nif(oldStyle)oldStyle.remove();\nconst st=document.createElement('style');\nst.id='v1047-three-vaults-style';\nst.textContent=`\n.v1042VaultModal{grid-template-rows:auto auto auto minmax(0,1fr)!important}\n.v1042VaultFoot{display:none!important}\n.v1047BankSection{padding-bottom:14px}\n.v1047BankButton{margin:0!important}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){\n  V.migrate(RF.state);\n  RF.save?.(RF.state);\n  setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0);\n}\n})();\n","js/v10_51.js":"window.RF=window.RF||{};\nRF.VERSION='10.51.0';\nRF.BUILD={\n  version:'10.51.0',\n  title:'Vault Trim',\n  built:'17 Sep 2026 • 03:27 BST',\n  buildId:'20260917-0327-bst'\n};\nRF.V1051=RF.V1051||{};\n\n/* Realmforge V10.51 — Vault Trim\n   - Removes the redundant secondary Pack/Bank count beside the Vault category filters.\n   - The Pack and Bank tabs at the top remain the single source of capacity/storage counts.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1051;\n\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.51.0';\n  s.v1051=s.v1051||{};\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\n// V10.42 writes a second count beside the category controls. The top Pack/Bank tabs already\n// show the same information, so remove that duplicate from the rendered Vault markup entirely.\nconst modalBase=RF.UI.modalHtml.bind(RF.UI);\nRF.UI.modalHtml=function(s){\n  let h=modalBase(s);\n  if(this.modal?.type==='bank')h=h.replace(/<div class=\"v1042VaultCount\">[\\s\\S]*?<\\/div>/,'');\n  return h;\n};\n\nconst oldStyle=document.getElementById('v1051-vault-trim-style');\nif(oldStyle)oldStyle.remove();\nconst st=document.createElement('style');\nst.id='v1051-vault-trim-style';\nst.textContent=`\n.v1042VaultTools{grid-template-columns:minmax(0,1fr)!important}\n.v1042VaultCount{display:none!important}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n","js/v10_52.js":"window.RF=window.RF||{};\nRF.VERSION='10.52.0';\nRF.BUILD={\n  version:'10.52.0',\n  title:'Quick Stack',\n  built:'17 Sep 2026 • 03:36 BST',\n  buildId:'20260917-0336-bst'\n};\nRF.V1052=RF.V1052||{};\n\n/* Realmforge V10.52 — Quick Stack\n   - Adds a one-tap Pack -> Bank quick-stack action inside the Vault.\n   - Only items that already have a stored Bank stack are moved.\n   - Equipped copies remain protected exactly as with normal deposits.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1052;\nconst B=RF.V1042;\n\nV.migrate=function(s){\n  if(!s)return s;\n  s.version='10.52.0';\n  s.v1052=s.v1052||{};\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\nV.stackable=function(s){\n  if(!s||!B)return [];\n  return Object.keys(s.inventory||{}).map(id=>{\n    const bankQty=Math.max(0,Number(s.bank?.[id])||0);\n    const move=B.packMovable(s,id);\n    return {id,move,bankQty};\n  }).filter(x=>x.bankQty>0&&x.move>0);\n};\nV.summary=function(s){\n  const rows=V.stackable(s);\n  return {stacks:rows.length,items:rows.reduce((n,x)=>n+x.move,0)};\n};\nV.quickStack=function(){\n  const s=RF.state;\n  if(!s||!RF.isBankTown?.(s)||RF.UI.modal?.type!=='bank'||!B)return;\n  const rows=V.stackable(s);\n  if(!rows.length){\n    RF.animateDenied?.('[data-v1052-quick-stack]');\n    return;\n  }\n  let items=0;\n  for(const {id,move} of rows){\n    if(move<1)continue;\n    RF.takeItem(s,id,move);\n    s.bank=s.bank||{};\n    s.bank[id]=(s.bank[id]||0)+move;\n    items+=move;\n  }\n  s.stats=s.stats||{};\n  s.stats.bankTransfers=(s.stats.bankTransfers||0)+items;\n  RF.log?.(s,`Quick stacked ${items} item${items===1?'':'s'} across ${rows.length} bank stack${rows.length===1?'':'s'}.`);\n  if(RF.UI.modal?.type==='bank')delete RF.UI.modal.v1042Qty;\n  RF.save?.(s);\n  RF.UI.render(s);\n};\n\n// Insert the action between the main Pack/Bank tabs and the category controls.\nconst modalBase=RF.UI.modalHtml.bind(RF.UI);\nRF.UI.modalHtml=function(s){\n  let h=modalBase(s);\n  if(this.modal?.type!=='bank'||!B)return h;\n  const sum=V.summary(s);\n  const label=sum.items>0?`${sum.items} item${sum.items===1?'':'s'} • ${sum.stacks} stack${sum.stacks===1?'':'s'}`:'No matching Pack stacks';\n  const quick=`<button type=\"button\" class=\"v1052QuickStack\" data-v1052-quick-stack ${sum.items<1?'disabled':''}><span class=\"v1052QuickIcon\">⚡</span><span><b>Quick Stack</b><small>Pack → Bank • ${label}</small></span></button>`;\n  h=h.replace(/(<div class=\"v1042VaultTabs\">[\\s\\S]*?<\\/div>)/,`$1${quick}`);\n  return h;\n};\n\nconst bindBase=RF.UI.bind.bind(RF.UI);\nRF.UI.bind=function(s){\n  bindBase(s);\n  document.querySelector('[data-v1052-quick-stack]')?.addEventListener('click',V.quickStack);\n};\n\nconst oldStyle=document.getElementById('v1052-quick-stack-style');\nif(oldStyle)oldStyle.remove();\nconst st=document.createElement('style');\nst.id='v1052-quick-stack-style';\nst.textContent=`\n.v1042VaultModal{grid-template-rows:auto auto auto auto minmax(0,1fr)!important}\n.v1052QuickStack{appearance:none;width:100%;min-height:46px;border-radius:14px;border:1px solid rgba(201,159,84,.25);background:linear-gradient(180deg,rgba(49,36,22,.9),rgba(22,16,11,.98));color:#ead8ad;display:flex;align-items:center;gap:10px;padding:8px 12px;text-align:left;box-shadow:inset 0 1px rgba(255,255,255,.04)}\n.v1052QuickStack:not(:disabled):active{transform:translateY(1px);filter:brightness(1.08)}\n.v1052QuickStack:disabled{opacity:.42;filter:saturate(.55)}\n.v1052QuickIcon{width:30px;height:30px;display:grid;place-items:center;border-radius:10px;background:rgba(198,157,89,.09);border:1px solid rgba(198,157,89,.17);font-size:17px;flex:0 0 auto}\n.v1052QuickStack>span:last-child{min-width:0;display:grid;gap:2px}.v1052QuickStack b{font-size:12px;color:#f0d79e}.v1052QuickStack small{font-size:9.5px;color:#a99a80;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n@media(max-width:430px){.v1052QuickStack{min-height:43px;padding:7px 10px}.v1052QuickIcon{width:28px;height:28px}.v1052QuickStack b{font-size:11.5px}.v1052QuickStack small{font-size:9px}}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n","js/v10_56.js":"window.RF=window.RF||{};\nRF.VERSION='10.56.0';\nRF.BUILD={\n  version:'10.56.0',\n  title:'Overburdened',\n  built:'17 Sep 2026 • 15:58 BST',\n  buildId:'20260917-1558-bst'\n};\nRF.V1056=RF.V1056||{};\n\n/* Realmforge V10.56 — Overburdened\n   - Pack acquisitions are lossless: new item stacks may temporarily exceed Pack capacity.\n   - Being above capacity pauses simulated time and prevents travel until the Pack is sorted.\n   - The Pack page shows a prominent over-encumbered warning and exact excess-slot count.\n   - Detached Equipment / Tool Belt returns may overflow safely instead of deleting or blocking gear.\n   - Existing saves/loadouts migrate in place; nothing valid is unequipped or discarded.\n*/\n\n(()=>{\n'use strict';\nconst V=RF.V1056;\nV.version='10.56.0';\nV.LEGACY_PICKS={master_lockpick:2,fine_lockpick:4,master_picks:8};\nV.escape=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nV.cap=s=>RF.packCapacity?Math.max(0,+RF.packCapacity(s)||0):Math.max(0,+RF.V82?.PACK_CAP||28);\nV.used=s=>RF.packUsed?Math.max(0,+RF.packUsed(s)||0):Object.values(s?.inventory||{}).filter(q=>(+q||0)>0).length;\nV.excess=s=>Math.max(0,V.used(s)-V.cap(s));\nV.isOver=s=>V.excess(s)>0;\nRF.isOverEncumbered=V.isOver;\nRF.packExcess=V.excess;\n\nV.syncPauseSnapshots=function(s){\n  if(!s)return;\n  if(RF.V96){\n    if(RF.V96.modalResume){RF.V96.modalResume.speed=0;RF.V96.modalResume.paused=true;RF.V96.modalResume.boostRemaining=0}\n    if(RF.V96.selectResume){RF.V96.selectResume.speed=0;RF.V96.selectResume.paused=true;RF.V96.selectResume.boostRemaining=0}\n    RF.V96.lastNonZeroSpeed=RF.V96.lastNonZeroSpeed||1;\n  }\n};\nV.enforcePause=function(s,{log=false}={}){\n  if(!s||!V.isOver(s))return false;\n  const wasMoving=(+s.speed||0)>0||!s.paused;\n  s.speed=0;s.paused=true;\n  if(s.v8){s.v8.boostUntil=0}\n  V.syncPauseSnapshots(s);\n  s.v1056=s.v1056||{};\n  if(log&&wasMoving&&!s.v1056.pauseLogged){\n    RF.log?.(s,`Pack over capacity (${V.used(s)}/${V.cap(s)} slots). Time and travel pause until you free ${V.excess(s)} slot${V.excess(s)===1?'':'s'}.`,'bad');\n    s.v1056.pauseLogged=true;\n  }\n  return true;\n};\nV.clearResolvedFlag=function(s){\n  if(!s)return;\n  s.v1056=s.v1056||{};\n  if(!V.isOver(s))s.v1056.pauseLogged=false;\n};\nV.warningText=function(s){\n  const used=V.used(s),cap=V.cap(s),ex=V.excess(s);\n  return `Your Pack is ${ex} slot${ex===1?'':'s'} over capacity (${used}/${cap}). Time and travel are locked until you bank, drop, sell, use or equip enough items to return to ${cap}/${cap} or lower.`;\n};\nV.warn=function(s=RF.state,title='Over-encumbered'){\n  if(!s)return false;\n  V.enforcePause(s);\n  RF.UI.modal={type:'message',title,text:V.warningText(s)};\n  RF.save?.(s);RF.UI.render(s);return false;\n};\nV.canPassTime=s=>!V.isOver(s);\nRF.canPassTime=V.canPassTime;\n\n// Future migrations can always return invalidated loadout items here. This deliberately\n// permits a temporary 31/30-style Pack rather than deleting gear or blocking migration.\nV.forceToPack=function(s,id,qty=1,reason='Loadout item returned to Pack'){\n  if(!s||!id)return false;\n  qty=Math.floor(Number(qty)||0);if(qty<=0)return false;\n  s.inventory=s.inventory||{};s.inventory[id]=(s.inventory[id]||0)+qty;\n  if(s.collection?.items)s.collection.items[id]=true;\n  RF.log?.(s,`${reason}: ${qty} × ${RF.DATA.items?.[id]?.name||id}.`,'important');\n  V.enforcePause(s,{log:true});\n  return true;\n};\nRF.forceLoadoutItemToPack=V.forceToPack;\n\n// Lossless item intake. V8.2 used to bank or discard brand-new overflow stacks; from V10.56\n// every legitimate acquisition lands in the Pack first and the player gets to sort it out.\nRF.addItem=function(s,id,q=1){\n  if(!s||!id)return false;\n  q=Math.floor(Number(q)||0);if(q<=0)return false;\n  if(V.LEGACY_PICKS[id]){q*=V.LEGACY_PICKS[id];id='lockpick'}\n  s.inventory=s.inventory||{};\n  s.inventory[id]=(s.inventory[id]||0)+q;\n  if(s.collection?.items)s.collection.items[id]=true;\n  V.enforcePause(s,{log:true});\n  return true;\n};\n\n// Detached loadout returns/swaps must never destroy an item because the Pack happens to be full.\nif(RF.V1053){\n  RF.V1053.addPackOne=function(s,id){return V.forceToPack(s,id,1,'Loadout item returned to Pack')};\n  RF.V1053.canSwap=function(s,newId){return Math.max(0,Number(s?.inventory?.[newId])||0)>0};\n}\n\n// Active gathering/crafting and market purchases may create overflow too. The penalty is the\n// resulting time lock, not disappearance of the reward.\nif(RF.V1022)RF.V1022.canReceiveGather=()=>true;\nV.craftAnalysis=function(s,id){\n  const r=RF.DATA.recipes?.[id];\n  if(!r)return {max:0,blockers:['Recipe data is unavailable.'],materialMax:0};\n  const blockers=[];\n  const level=s.skills?.[r.skill]?.level||1;\n  if(level<r.level)blockers.push(`Requires ${RF.DATA.skills?.[r.skill]?.name||r.skill} Lv ${r.level} (you are Lv ${level}).`);\n  let materialMax=Infinity;\n  for(const [itemId,qty] of Object.entries(r.inputs||{})){\n    const have=RF.V1019?.craftCount?RF.V1019.craftCount(s,itemId):Math.max(0,+s.inventory?.[itemId]||0);\n    materialMax=Math.min(materialMax,Math.floor(have/qty));\n    if(have<qty){\n      const pack=Math.max(0,+s.inventory?.[itemId]||0),bank=RF.V1019?.bankCount?RF.V1019.bankCount(s,itemId):0;\n      const where=RF.V1019?.canUseBank?.(s)?`pack ${pack} + bank ${bank}`:`pack ${pack}`;\n      blockers.push(`Need ${qty} × ${RF.DATA.items?.[itemId]?.name||itemId} (you have ${have}: ${where}).`);\n    }\n  }\n  if(!Number.isFinite(materialMax))materialMax=0;\n  materialMax=Math.max(0,materialMax);\n  if(blockers.length)return {max:0,blockers,materialMax};\n  return {max:materialMax,blockers:[],materialMax};\n};\nif(RF.V1019)RF.V1019.craftAnalysis=V.craftAnalysis;\nif(RF.V1015){RF.V1015.craftAnalysis=V.craftAnalysis;RF.V1015.recipeState=function(s,id,r){const a=V.craftAnalysis(s,id),lvl=s.skills?.[r.skill]?.level||1;if(lvl<r.level)return {label:`LV ${r.level}`,ready:false};if(a.materialMax<1)return {label:'MATS',ready:false};return {label:'READY',ready:true}}}\nRF.v9MaxCraft=function(s,id){return V.craftAnalysis(s,id).max};\nRF.v9MaxBuy=function(s,id,price){\n  const it=RF.DATA.items?.[id];if(!it)return 0;\n  return Math.max(0,Math.floor((s.gold||0)/Math.max(1,price||1)));\n};\nif(RF.V1054){\n  RF.V1054.buyMax=function(s,loc,id){\n    const rec=RF.V1054.ensureStock(s,loc),stock=Math.max(0,Number(rec?.stock?.[id])||0),price=RF.V1054.buyPrice(s,loc,id);\n    if(stock<1||price<1)return 0;\n    return Math.min(stock,Math.max(0,Math.floor((s.gold||0)/price)));\n  };\n}\n\n// Time cannot move while burdened. Returning false lets newer callers detect the block while\n// older callers simply receive a harmless no-op instead of advancing the world clock.\nconst advanceBase=RF.advanceWorld;\nRF.advanceWorld=function(minutes){\n  const s=RF.state;\n  if(s&&V.isOver(s)){V.enforcePause(s);return false}\n  return advanceBase.apply(this,arguments);\n};\n\nconst speedBase=RF.setSpeed;\nRF.setSpeed=function(v){\n  const s=RF.state;\n  if(s&&+v>0&&V.isOver(s))return V.warn(s);\n  const out=speedBase.apply(this,arguments);V.clearResolvedFlag(RF.state);return out;\n};\n\nconst travelBase=RF.travel;\nRF.travel=function(){\n  const s=RF.state;\n  if(s&&V.isOver(s))return V.warn(s,'Too burdened to travel');\n  return travelBase.apply(this,arguments);\n};\n\nconst startActivityBase=RF.startActivity;\nRF.startActivity=function(type){\n  const s=RF.state;\n  if(s&&V.isOver(s))return V.warn(s,type==='travel'?'Too burdened to travel':'Pack must be sorted first');\n  return startActivityBase.apply(this,arguments);\n};\n\n// Explicit long rests should not grant free recovery when advanceWorld is blocked.\nif(typeof RF.restAtHome==='function'){\n  const restHomeBase=RF.restAtHome;\n  RF.restAtHome=function(){if(V.isOver(RF.state))return V.warn(RF.state,'Too burdened to rest');return restHomeBase.apply(this,arguments)};\n}\nif(typeof RF.v10RestUntil==='function'){\n  const restInnBase=RF.v10RestUntil;\n  RF.v10RestUntil=function(){if(V.isOver(RF.state))return V.warn(RF.state,'Too burdened to rest');return restInnBase.apply(this,arguments)};\n}\n\n// Time-costing active minigames also respect the lock. Pack-management actions, combat,\n// dialogue and ordinary UI remain available so the player can solve the overload.\nV.guardStart=function(name,fn){if(typeof fn!=='function')return fn;return function(){if(V.isOver(RF.state))return V.warn(RF.state,'Pack must be sorted first');return fn.apply(this,arguments)}};\nif(typeof RF.v9StartCraftQty==='function')RF.v9StartCraftQty=V.guardStart('craft',RF.v9StartCraftQty);\nif(typeof RF.startExcavation==='function')RF.startExcavation=V.guardStart('excavation',RF.startExcavation);\nif(typeof RF.startPotionLab==='function')RF.startPotionLab=V.guardStart('herblore',RF.startPotionLab);\nif(typeof RF.cookAtFire==='function')RF.cookAtFire=V.guardStart('cooking',RF.cookAtFire);\nif(RF.V1024?.startHomeCook)RF.V1024.startHomeCook=V.guardStart('cooking',RF.V1024.startHomeCook);\nif(typeof RF.lightFire==='function')RF.lightFire=V.guardStart('firemaking',RF.lightFire);\nif(typeof RF.startLockpick==='function')RF.startLockpick=V.guardStart('lockpicking',RF.startLockpick);\nif(typeof RF.startPickpocket==='function')RF.startPickpocket=V.guardStart('pickpocket',RF.startPickpocket);\nif(typeof RF.researchEnemy==='function')RF.researchEnemy=V.guardStart('research',RF.researchEnemy);\n\n// If road loot/event rewards make the Pack overflow, keep the journey record paused but hide the\n// travel overlay so the player can actually open Pack, drop/use items, or use a bank at the origin.\nif(RF.V1017?.mountOverlay){\n  const overlayBase=RF.V1017.mountOverlay.bind(RF.V1017);\n  RF.V1017.mountOverlay=function(s){if(V.isOver(s)){V.enforcePause(s);return}return overlayBase(s)};\n}\n\nV.migrate=function(s){\n  if(!s)return s;\n  s.v1056=s.v1056||{};s.inventory=s.inventory||{};\n  // Keep valid existing Equipment/Tool Belt loadouts exactly where they are. V10.53 remains the\n  // owner of detached-loadout migration; we only add overflow-safe return semantics from now on.\n  if(RF.V1053?.migrate)RF.V1053.migrate(s);\n  s.version='10.56.0';\n  V.enforcePause(s,{log:false});V.clearResolvedFlag(s);\n  return s;\n};\n/* V11.8: legacy save/migration wrapper extracted to canonical core. */\n\n// Pack warning + count treatment.\nconst inventoryBase=RF.UI.inventory.bind(RF.UI);\nRF.UI.inventory=function(s){\n  let h=inventoryBase(s),used=V.used(s),cap=V.cap(s),ex=V.excess(s);\n  if(!ex)return h;\n  const warning=`<div class=\"v1056OverWarning\"><div class=\"v1056WarnIcon\">⚠️</div><div><b>OVER-ENCUMBERED • +${ex} SLOT${ex===1?'':'S'}</b><span>${used}/${cap} Pack slots. Time and travel are paused until you bank, drop, sell, use or equip enough items.</span></div></div>`;\n  h=h.replace(/(<div class=\"v1046CatGrid\"[^>]*>)/,warning+'$1');\n  h=h.replace('packCount full','packCount full v1056OverCount');\n  return h;\n};\n\n// Give the top time controls a visibly locked state while still allowing taps to explain why.\nconst topBase=RF.UI.top?.bind(RF.UI);\nif(topBase)RF.UI.top=function(s){\n  let h=topBase(s);if(!V.isOver(s))return h;\n  return h.replace(/class=\"speed ([^\"]*)\" data-speed=\"([12])\"/g,(m,cls,v)=>`class=\"speed ${cls} v1056TimeLocked\" data-speed=\"${v}\" aria-disabled=\"true\" title=\"Free Pack space to resume time\"`);\n};\n\n// Final render guard catches older systems that restore a pre-combat/pre-modal speed after loot.\nconst renderBase=RF.UI.render.bind(RF.UI);\nRF.UI.render=function(s){if(s)V.enforcePause(s,{log:false});const out=renderBase(s);if(s&&!V.isOver(s))V.clearResolvedFlag(s);return out};\n\nconst st=document.createElement('style');st.id='v1056-overburdened-style';st.textContent=`\n.v1056OverWarning{display:grid;grid-template-columns:38px minmax(0,1fr);gap:10px;align-items:center;padding:11px 12px;border:1px solid rgba(207,91,73,.62);border-radius:15px;background:linear-gradient(180deg,rgba(91,31,24,.46),rgba(47,19,16,.58));box-shadow:inset 0 1px rgba(255,255,255,.035)}\n.v1056WarnIcon{width:36px;height:36px;display:grid;place-items:center;border-radius:12px;background:rgba(155,54,42,.28);font-size:21px}.v1056OverWarning b{display:block;color:#f2b49f;font-size:12px;letter-spacing:.06em}.v1056OverWarning span{display:block;margin-top:3px;color:#d7b9ae;font-size:10.5px;line-height:1.35}\n.v1056OverCount{color:#ef9e89!important}.speed.v1056TimeLocked{opacity:.42!important;border-color:rgba(183,88,70,.35)!important;color:#c99d94!important;filter:saturate(.55)}\n`;\ndocument.head.appendChild(st);\n\nif(RF.state){V.migrate(RF.state);RF.save?.(RF.state);setTimeout(()=>{if(RF.state&&!RF.V101?.mainMenu)RF.UI.render(RF.state)},0)}\n})();\n"};
  const installed=[];
  const installedSet=new Set();
  function runClassic(name) {
    if(installedSet.has(name)) return false;
    const source=sources[name];
    if(typeof source!=='string') throw new Error(`Unknown canonical Inventory stage: ${name}`);
    const script=document.createElement('script');
    script.type='text/javascript';
    script.setAttribute('data-rf-canonical-stage',name);
    script.textContent=source+`\n//# sourceURL=realmforge-canonical:///inventory/${name.replace(/^js\//,'')}\n`;
    (document.head||document.documentElement).appendChild(script);
    script.remove();
    installedSet.add(name);installed.push(name);
    return true;
  }
  const api={

    quantity: (state,id) => Math.max(0,Number(state?.inventory?.[id])||0),
    add: (state,id,qty=1) => RF.addItem(state,id,qty),
    take: (state,id,qty=1) => RF.takeItem(state,id,qty),
    has: (state,req) => RF.hasItems(state,req),
    capacity: state => typeof RF.packCapacity==='function' ? RF.packCapacity(state) : Infinity,
    free: state => typeof RF.packFree==='function' ? RF.packFree(state) : Infinity,
    drop: (id,all=false) => typeof RF.dropItem==='function' ? RF.dropItem(id,all) : false,
    use: id => RF.useItem(id),
    openItem: id => typeof RF.openItem==='function' ? RF.openItem(id) : null,
    openBank: () => typeof RF.openBank==='function' ? RF.openBank() : null,
    installHistoricalStage: runClassic,
    installedStages: installed,
    ownsStage: name => Object.prototype.hasOwnProperty.call(sources,name),
    stageNames: () => Object.keys(sources)
  };
  RF.Systems.Inventory=RF.Modules.register('systems.inventory',api,{owner:'systems',status:'canonical',historicalStageCount:Object.keys(sources).length,extractedIn:'11.13.0'});
})();
